def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))

    def edge_run(row):
        cells = [(c, grid[row][c]) for c in range(w) if grid[row][c] != bg]
        if not cells:
            return None
        color = cells[0][1]
        cols = [c for c, v in cells if v == color]
        return color, min(cols), max(cols)

    top = edge_run(0)
    bottom = edge_run(h - 1)
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
              if grid[r][c] != bg and grid[r][c] not in
              ({top[0]} if top else set())]
    # The interior singleton is the non-background cell not belonging to the edge-marker color.
    r, c, color = points[0]

    if top and bottom:
        offset = c - top[1]
        other_c = bottom[1] + offset

        # Extend from the top edge down to the singleton.
        for rr in range(1, r):
            if out[rr][c] == bg:
                out[rr][c] = color

        # Draw the corresponding full-height line at the translated position.
        if 0 <= other_c < w:
            for rr in range(h):
                if out[rr][other_c] == bg:
                    out[rr][other_c] = color

    out[r][c] = 4
    return out
